fn at(secs: u64, body: &str) -> LogRecord {
    let mut r = LogRecord::new(Severity::Info, body).with_attribute("k", format!("v-{body}"));
    r.timestamp = UNIX_EPOCH + Duration::from_secs(secs);
    r.resource.insert("service.name".into(), "svc".into());
    r
}

async fn filled() -> MemoryLogExporter {
    let exp = MemoryLogExporter::new();
    let records: Vec<LogRecord> = (1..=5).map(|i| at(i, &format!("r{i}"))).collect();
    exp.export(&records, Default::default()).await.unwrap();
    exp
}

#[tokio::test]
async fn memory_search_filters_orders_and_pages() {
    let exp = filled().await;
    assert!(!exp.is_empty());
    assert!(format!("{exp:?}").contains("records: 5"));
    let q = exp.query();
    let all = q.search("*", SearchOptions::default()).await.unwrap();
    assert_eq!(all.total, Some(5));
    assert_eq!(all.records[0].body, "r5", "newest first by default");
    assert_eq!(all.next_cursor, None);

    let page = q
        .search("", SearchOptions::default().order(SortOrder::Asc).limit(2))
        .await
        .unwrap();
    assert_eq!(
        page.records
            .iter()
            .map(|r| r.body.as_str())
            .collect::<Vec<_>>(),
        ["r1", "r2"]
    );
    let next = page.next_cursor.unwrap();
    let page2 = q
        .search(
            "",
            SearchOptions::default()
                .order(SortOrder::Asc)
                .limit(2)
                .cursor(next),
        )
        .await
        .unwrap();
    assert_eq!(page2.records[0].body, "r3");

    let ranged = q
        .search(
            "r",
            SearchOptions::default().range(
                Some(UNIX_EPOCH + Duration::from_secs(2)),
                Some(UNIX_EPOCH + Duration::from_secs(3)),
            ),
        )
        .await
        .unwrap();
    assert_eq!(ranged.records.len(), 2);
    assert_eq!(
        q.search("v-r4", SearchOptions::default())
            .await
            .unwrap()
            .records
            .len(),
        1
    );
    let err = q
        .search("", SearchOptions::default().cursor("nope"))
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Validation);
    assert_eq!(q.list_streams().await.unwrap(), ["default"]);
    assert_eq!(q.list_labels().await.unwrap(), ["k", "service.name"]);
    let json = serde_json::to_value(&page2).unwrap();
    assert_eq!(json["nextCursor"], "4");
    assert_eq!(json["total"], 5);
    exp.clear();
    assert_eq!(exp.len(), 0);
}

#[tokio::test(start_paused = true)]
async fn wait_for_log_polls_until_match_or_timeout() {
    let exp = MemoryLogExporter::new();
    let q = Arc::new(exp.query());
    let writer = {
        let exp = exp.clone();
        tokio::spawn(async move {
            tokio::time::sleep(Duration::from_secs(2)).await;
            exp.export(&[at(1, "other"), at(2, "target")], Default::default())
                .await
                .unwrap();
        })
    };
    let opts = WaitOptions::default()
        .timeout(Duration::from_secs(10))
        .interval(Duration::from_millis(500))
        .predicate(|r| r.body == "target");
    assert!(format!("{opts:?}").contains("predicate: true"));
    let found = q.wait_for_log("", opts).await.unwrap();
    assert_eq!(found.body, "target");
    writer.await.unwrap();

    let err = wait_for_log(q.as_ref(), "missing", WaitOptions::default())
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Timeout);
    let d = WaitOptions::default();
    assert_eq!(
        (d.timeout, d.interval),
        (Duration::from_secs(30), Duration::from_secs(1))
    );
}

struct Bare {
    calls: AtomicUsize,
}

#[async_trait]
impl LogQueryClient for Bare {
    async fn search(&self, _query: &str, _opts: SearchOptions) -> Result<LogSearchResult> {
        match self.calls.fetch_add(1, Ordering::SeqCst) {
            0 => Err(Error::unavailable("flaky")),
            1 => Ok(LogSearchResult::default()),
            _ => Err(Error::new(ErrorCode::Authentication, "bad token")),
        }
    }
}

#[tokio::test(start_paused = true)]
async fn defaults_are_unsupported_and_errors_propagate() {
    let q = Bare {
        calls: AtomicUsize::new(0),
    };
    let unsupported = |e: Error| assert_eq!(e.code(), ErrorCode::Unsupported);
    unsupported(q.list_streams().await.unwrap_err());
    unsupported(q.list_labels().await.unwrap_err());
    unsupported(
        q.tail("x", Arc::new(|_| {}), TailOptions::default())
            .await
            .unwrap_err(),
    );
    // Retryable error and empty page keep polling; the authentication error stops it.
    let err = q
        .wait_for_log("x", WaitOptions::default())
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Authentication);
    let d = SearchOptions::default();
    assert_eq!(
        (d.limit, d.order, d.start, d.cursor),
        (100, SortOrder::Desc, None, None)
    );
}

#[tokio::test]
async fn tail_handle_and_polling_tail() {
    let h = TailHandle::default();
    assert!(!h.is_stopped());
    assert!(format!("{h:?}").contains("false"));
    let h2 = h.clone();
    let waiter = tokio::spawn(async move { h2.stopped().await });
    tokio::task::yield_now().await;
    h.stop();
    h.stop();
    waiter.await.unwrap();
    h.stopped().await; // already stopped → returns at once

    let exp = MemoryLogExporter::new();
    let start = SystemTime::now() - Duration::from_secs(60);
    let mut old = at(0, "old");
    old.timestamp = start - Duration::from_secs(1);
    let mut same = [at(0, "a"), at(0, "b")];
    for r in &mut same {
        r.timestamp = start + Duration::from_secs(1);
    }
    exp.export(&[old], Default::default()).await.unwrap();
    exp.export(&same, Default::default()).await.unwrap();
    let seen = Arc::new(Mutex::new(Vec::<String>::new()));
    let s2 = seen.clone();
    let opts = TailOptions {
        interval: Duration::from_millis(20),
        start: Some(start),
    };
    let handle = exp
        .query()
        .tail("", Arc::new(move |r| s2.lock().unwrap().push(r.body)), opts)
        .await
        .unwrap();
    tokio::time::sleep(Duration::from_millis(100)).await;
    let mut late = at(0, "late");
    late.timestamp = start + Duration::from_secs(2);
    exp.export(&[late], Default::default()).await.unwrap();
    for _ in 0..100 {
        if seen.lock().unwrap().len() >= 3 {
            break;
        }
        tokio::time::sleep(Duration::from_millis(10)).await;
    }
    handle.stop();
    tokio::time::sleep(Duration::from_millis(50)).await;
    let mut got = seen.lock().unwrap().clone();
    got.sort();
    assert_eq!(
        got,
        ["a", "b", "late"],
        "each record once, nothing before start"
    );
    assert_eq!(TailOptions::default().interval, Duration::from_secs(1));
}

