#[tokio::test]
async fn polling_tail_survives_errors_and_stops_mid_page() {
    let h = poll_tail(
        Arc::new(Failing),
        "q",
        Arc::new(|_| {}),
        TailOptions {
            interval: Duration::from_millis(5),
            start: None,
        },
    );
    tokio::time::sleep(Duration::from_millis(30)).await;
    h.stop();

    // A callback that stops the tail while a page is being delivered.
    let exp = MemoryLogExporter::new();
    let start = SystemTime::now();
    let mut records = [at(0, "x"), at(0, "y")];
    records[0].timestamp = start + Duration::from_secs(1);
    records[1].timestamp = start + Duration::from_secs(2);
    exp.export(&records, Default::default()).await.unwrap();
    let count = Arc::new(AtomicUsize::new(0));
    let holder: Arc<Mutex<Option<TailHandle>>> = Arc::default();
    let (c2, h2) = (count.clone(), holder.clone());
    let handle = poll_tail(
        Arc::new(exp.query()),
        "",
        Arc::new(move |_| {
            c2.fetch_add(1, Ordering::SeqCst);
            if let Some(h) = h2.lock().unwrap().as_ref() {
                h.stop();
            }
        }),
        TailOptions {
            interval: Duration::from_millis(5),
            start: Some(start),
        },
    );
    *holder.lock().unwrap() = Some(handle.clone());
    tokio::time::sleep(Duration::from_millis(50)).await;
    assert!(handle.is_stopped());
    assert_eq!(count.load(Ordering::SeqCst), 1);
}

