#[tokio::test]
async fn polling_tail_stops_during_inflight_search_and_interval_or() {
    let h = poll_tail(
        Arc::new(Hanging),
        "q",
        Arc::new(|_| {}),
        TailOptions::default(),
    );
    tokio::time::sleep(Duration::from_millis(20)).await;
    h.stop();
    assert!(h.is_stopped());

    let service = Duration::from_secs(5);
    assert_eq!(TailOptions::default().interval_or(service), service);
    let zero = TailOptions {
        interval: Duration::ZERO,
        start: None,
    };
    assert_eq!(zero.interval_or(service), service);
    let custom = TailOptions {
        interval: Duration::from_millis(250),
        start: None,
    };
    assert_eq!(custom.interval_or(service), Duration::from_millis(250));
    assert_eq!(TailOptions::DEFAULT_INTERVAL, Duration::from_secs(1));
}

#[test]
fn timestamps_are_public() {
    use sdk::logging::{format_timestamp, parse_timestamp};
    let t = UNIX_EPOCH + Duration::from_nanos(1_700_000_000_123_456_789);
    let text = format_timestamp(t);
    assert_eq!(text, "2023-11-14T22:13:20.123456789Z");
    assert_eq!(parse_timestamp(&text).unwrap(), t);
    assert_eq!(
        sdk::logging::record::parse_timestamp("2023-11-14T23:13:20.123456789+01:00").unwrap(),
        t
    );
    assert_eq!(
        parse_timestamp("nope").unwrap_err().code(),
        ErrorCode::Validation
    );
}
